WHERE NOT EXISTS {
  MATCH (:Column)-[t:TRANSFORMS_TO]->(out:Column)
  WHERE t.scenario = j.name
    AND EXISTS { MATCH (out)-[:TRANSFORMS_TO*0..]->(:Column)-[:FEEDS]->(:FinalConsumer) }
